import com.intellij.psi.PsiParameter;
import com.intellij.psi.PsiParameterList;
import com.intellij.psi.PsiType;
import java.util.Collections;
import java.util.List;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.uast.UBlockExpression;
import org.jetbrains.uast.UCallExpression;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UElement;
import org.jetbrains.uast.UExpression;
import org.jetbrains.uast.ULambdaExpression;
import org.jetbrains.uast.ULiteralExpression;
import org.jetbrains.uast.UMethod;
import org.jetbrains.uast.UParenthesizedExpression;
import org.jetbrains.uast.UReturnExpression;

public class AllowAllHostnameVerifierDetector extends Detector implements SourceCodeScanner {
    private static final String HOSTNAME_VERIFIER = "javax.net.ssl.HostnameVerifier";
    private static final String SSL_SESSION = "javax.net.ssl.SSLSession";
    private static final String MESSAGE = "Insecure HostnameVerifier: verify() always returns true, which trusts any hostname";

    public static final Issue ISSUE = Issue.create(
        "AllowAllHostnameVerifier",
        "Insecure HostnameVerifier",
        "Using a HostnameVerifier whose verify() method always returns true causes the app to trust any hostname...",
        Category.SECURITY,
        6,
        Severity.WARNING,
        new Implementation(AllowAllHostnameVerifierDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Nullable
    @Override
    public List<String> applicableSuperClasses() {
        return Collections.singletonList(HOSTNAME_VERIFIER);
    }

    @Override
    public void visitClass(@NotNull JavaContext context, @NotNull UClass declaration) {
        for (UMethod method : declaration.getMethods()) {
            if (isVerifyMethodSignature(method) && alwaysReturnsTrue(context, method)) {
                context.report(ISSUE, method, context.getLocation(method), MESSAGE);
            }
        }
    }

    @Override
    public void visitClass(@NotNull JavaContext context, @NotNull ULambdaExpression lambda) {
        if (alwaysReturnsTrue(context, lambda.getBody())) {
            context.report(ISSUE, lambda, context.getLocation(lambda), MESSAGE);
        }
    }

    private static boolean isVerifyMethodSignature(@NotNull UMethod method) {
        if (!"verify".equals(method.getName())) return false;
        PsiType returnType = method.getReturnType();
        if (returnType == null || !PsiType.BOOLEAN.equals(returnType)) return false;
        PsiParameterList params = method.getParameterList();
        if (params.getParametersCount() != 2) return false;
        PsiParameter[] parameters = params.getParameters();
        PsiType first = parameters[0].getType();
        PsiType second = parameters[1].getType();
        return first != null && first.equalsToText("java.lang.String")
            && second != null && second.equalsToText(SSL_SESSION);
    }

    private static boolean alwaysReturnsTrue(@NotNull JavaContext context, @NotNull UMethod method) {
        UExpression body = method.getUastBody();
        return body != null && alwaysReturnsTrue(context, body);
    }

    private static boolean alwaysReturnsTrue(@NotNull JavaContext context, @Nullable UExpression expression) {
        if (expression == null) return false;
        if (isTrueLiteral(context, expression)) return true;
        if (expression instanceof UBlockExpression) {
            List<UExpression> expressions = ((UBlockExpression) expression).getExpressions();
            // single expression block: { return true; }
            if (expressions.size() == 1) {
                return isReturnTrue(context, expressions.get(0));
            }
            // handle multiple statements: every return must be true and function always returns
            // For simplicity, look for any return false/non-true; if only returns are true and at least one, accept.
            // But if there are statements after last return, they are unreachable and ignore.
            boolean sawTrueReturn = false;
            for (UExpression expr : expressions) {
                if (expr instanceof UReturnExpression) {
                    UExpression value = ((UReturnExpression) expr).getReturnExpression();
                    if (!isTrueLiteral(context, value)) {
                        return false;
                    }
                    sawTrueReturn = true;
                }
            }
            return sawTrueReturn;
        }
        return false;
    }

    private static boolean isReturnTrue(@NotNull JavaContext context, @Nullable UExpression expression) {
        if (!(expression instanceof UReturnExpression)) return false;
        UExpression returnValue = ((UReturnExpression) expression).getReturnExpression();
        return isTrueLiteral(context, returnValue);
    }

    private static boolean isTrueLiteral(@NotNull JavaContext context, @Nullable UExpression expression) {
        UExpression unwrapped = skipParentheses(expression);
        if (unwrapped instanceof ULiteralExpression) {
            Object value = ((ULiteralExpression) unwrapped).getValue();
            return Boolean.TRUE.equals(value);
        }
        return false;
    }

    @Nullable
    private static UExpression skipParentheses(@Nullable UExpression expression) {
        UExpression current = expression;
        while (current instanceof UParenthesizedExpression) {
            current = ((UParenthesizedExpression) current).getExpression();
        }
        return current;
    }
}
